  function openPalette(mode,clip=current()){closeV18Panels('v18Palette');paletteMode=mode;paletteClip=clip;const tabs=byId('v18PaletteTabs'),grid=byId('v18PaletteGrid');tabs.replaceChildren();grid.replaceChildren();byId('v18PaletteTitle').textContent=mode==='effect'?'Efeitos':mode==='transition'?'Transições':mode==='animation'?'Animações':'Modelos de legenda';byId('v18PaletteEyebrow').textContent=mode==='transition'?'ARRASTE ATÉ O CORTE':mode==='effect'?'ARRASTE SOBRE A MÍDIA':mode==='animation'?'ENTRADA / SAÍDA':'SEM ESTILO OBRIGATÓRIO';if(mode==='animation'){for(const [side,label] of [['in','Entrada'],['out','Saída']]){const b=document.createElement('button');b.textContent=label;b.className=paletteSide===side?'active':'';b.onclick=()=>{paletteSide=side;openPalette('animation',paletteClip);};tabs.append(b);}}if(mode==='effect'){for(const [id,label,icon,note] of effectDefs)grid.append(resourceCard('effect',id,label,icon,note));}else if(mode==='transition'){for(const [id,label,icon,note] of transitionDefs)grid.append(resourceCard('transition',id,label,icon,note));}else if(mode==='animation'){for(const name of (paletteSide==='in'?animIn:animOut))grid.append(resourceCard('animation',name,name,animationIcon(name),paletteSide==='in'?'Entrada':'Saída'));}else if(mode==='caption'){for(const [id,label] of [['clean','Limpa'],['social','Social'],['comic','HQ'],['card','Cartão'],['minimal','Minimal'],['highlight','Destaque']])grid.append(resourceCard('caption',id,label,'Aa','Legenda'));}byId('v18Palette').classList.remove('v18Hidden');}
  function animationIcon(name){if(name.includes('Zoom'))return '◉';if(name.includes('Fade'))return '◌';if(name.includes('Deslizar'))return '➜';if(name.includes('Giro'))return '⟳';if(name.includes('Bounce')||name.includes('Pop'))return '●';return '✦';}
  function resourceCard(kind,id,label,icon,note){const b=document.createElement('button');b.className='v18Card';b.dataset.kind=kind;b.dataset.resource=id;b.innerHTML=`<span class="v18Icon">${icon}</span><b>${label}</b><small>${note}</small>`;b.onclick=e=>{if(e.detail===0||!b.dataset.dragged)applyResource(kind,id,paletteClip);b.dataset.dragged='';};bindResourceDrag(b,kind,id,label);return b;}
  function findClipAtPoint(x,y,visual=true){const el=document.elementFromPoint(x,y)?.closest('.clip');if(!el)return null;const c=P.clips.find(c=>c.id===el.dataset.id);if(!c)return null;if(visual&&['audio','effect'].includes(c.type))return null;return c;}
  function nearestCutAt(x,y){const track=q('.track[data-track="main"]');if(!track)return null;const r=track.getBoundingClientRect();if(y<r.top-70||y>r.bottom+70)return null;let best=null,dist=64;for(const cut of cuts()){const px=r.left+cut.time*pps-byId('timelineScroll').scrollLeft;const d=Math.abs(x-px);if(d<dist){dist=d;best=cut;}}return best;}
  function clearDropHints(){qa('.v18DropTarget').forEach(n=>n.classList.remove('v18DropTarget'));qa('.cutTarget.v18').forEach(n=>n.remove());}
  function bindResourceDrag(card,kind,id,label){card.onpointerdown=e=>{if(e.button>0)return;const start={x:e.clientX,y:e.clientY};let dragging=false,ghost=null,target=null;const move=ev=>{if(!dragging&&Math.hypot(ev.clientX-start.x,ev.clientY-start.y)<7)return;if(!dragging){dragging=true;card.dataset.dragged='1';byId('v18Palette').classList.add('v18Hidden');ghost=document.createElement('div');ghost.className='v18DragGhost';ghost.textContent=label;document.body.append(ghost);}ghost.style.left=ev.clientX+'px';ghost.style.top=ev.clientY+'px';clearDropHints();target=null;if(kind==='transition'){target=nearestCutAt(ev.clientX,ev.clientY);if(target){const tr=q('.track[data-track="main"]'),line=document.createElement('div');line.className='cutTarget v18';line.style.left=target.time*pps+'px';tr.append(line);}}else{target=findClipAtPoint(ev.clientX,ev.clientY,kind!=='audio');if(target)q(`.clip[data-id="${CSS.escape(target.id)}"]`)?.classList.add('v18DropTarget');}};const up=ev=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);window.removeEventListener('pointercancel',up);clearDropHints();ghost?.remove();if(dragging&&target){if(kind==='transition')applyTransitionDef(id,target);else applyResource(kind,id,target);} };window.addEventListener('pointermove',move,{passive:false});window.addEventListener('pointerup',up,{once:true});window.addEventListener('pointercancel',up,{once:true});};}
  function applyResource(kind,id,target){if(kind==='effect'){const c=target&&target.type?target:current();if(!c||['audio','effect'].includes(c.type))return toast('Solte o efeito sobre uma mídia visual.');act(()=>{const fx=newClip('effect',effectDefs.find(x=>x[0]===id)?.[1]||'Efeito',null,'effects',c.start,c.duration);fx.preset=id;fx.intensity=70;fx.power=id==='wide'?32:0;fx.enabled=true;P.clips.push(fx);selected=fx.id;t=fx.start;});return;}if(kind==='animation'){const c=target&&target.type?target:current();if(!c||['audio','effect'].includes(c.type))return toast('Solte a animação sobre uma mídia visual.');act(()=>{c.animation??={};c.animation[paletteSide]={name:id,duration:.3,volume:0,soundAsset:null};});return;}if(kind==='caption')return applyCaptionPreset(id);}
  function applyTransitionDef(type,cut){if(!cut){const all=cuts();cut=all.sort((a,b)=>Math.abs(a.time-t)-Math.abs(b.time-t))[0];}if(!cut)return toast('Adicione dois clips consecutivos na faixa principal.');if(cut.a.duration<.25||cut.b.duration<.25)return toast('Os dois clips precisam ter pelo menos 0,25 s.');act(()=>{cut.b.transition={type,duration:.3,sound:'none',volume:0,from:cut.a.id};});}
  // Reuse TRAN button but open icon palette on click; dragging old behavior remains available.
