  // Connected transition compositor: always keep the next frame under the moving frame, never expose project background.
  const oldBlendFrames=blendFrames;
  blendFrames=function(g,A,B,tr,w,h){const u=tr.u??.5,s=u*u*(3-2*u),peak=Math.sin(Math.PI*u);const image=(im,x=0,y=0,scale=1,alpha=1,rot=0)=>{g.save();g.globalAlpha=alpha;g.translate(w/2+x,h/2+y);g.rotate(rot);g.scale(scale,scale);g.drawImage(im,-w/2,-h/2,w,h);g.restore();};g.save();g.setTransform(1,0,0,1,0,0);g.fillStyle='#101217';g.fillRect(0,0,w,h);image(B,0,0,1.035,1);if(tr.type==='left'||tr.type==='right'){const dir=tr.type==='left'?-1:1;image(A,dir*s*w,0,1.04,1);image(B,dir*(s-1)*w,0,1.04,1);}else if(tr.type==='pushUp'||tr.type==='pushDown'){const dir=tr.type==='pushUp'?-1:1;image(A,0,dir*s*h,1.04,1);image(B,0,dir*(s-1)*h,1.04,1);}else if(tr.type==='in'||tr.type==='out'){const dir=tr.type==='in'?1:-1;g.filter=`blur(${peak*3.2}px)`;image(A,0,0,1.03+dir*s*.18,1-s*.45);image(B,0,0,1.03-dir*(1-s)*.14,s);g.filter='none';}else if(tr.type==='zoomBlur'){g.filter=`blur(${peak*7}px)`;image(A,0,0,1.03+s*.28,1-s);image(B,0,0,1.28-s*.25,s);g.filter='none';}else if(tr.type==='wipeLeft'||tr.type==='wipeRight'){image(A,0,0,1.03,1);g.save();const x=tr.type==='wipeLeft'?w*(1-s):0;g.beginPath();g.rect(x,0,w*s,h);g.clip();image(B,0,0,1.03,1);g.restore();}else if(tr.type==='spin'){image(A,0,0,1.03+s*.18,1-s,s*.18);image(B,0,0,1.18-s*.15,s,-(1-s)*.13);}else if(tr.type==='blurMix'){g.filter=`blur(${peak*8}px)`;image(A,0,0,1.03,1-s);image(B,0,0,1.03,s);g.filter='none';}else if(tr.type==='mix'){image(A,0,0,1.03,1-s);image(B,0,0,1.03,s);}else{g.restore();return oldBlendFrames(g,A,B,tr,w,h);}g.restore();};

  // -----------------------------
  // Post effects: GPU-friendly canvas operations, editable effect clips
